-- A rule's multi-row INSERT ... VALUES action inserts every VALUES row for
-- one source row before the next, takes DEFAULT per row, fires statement
-- triggers once and returns rows; rules check their RETURNING lists.
CREATE TABLE src285 (a int, b text);
CREATE TABLE dst285 (id int GENERATED ALWAYS AS IDENTITY, a int DEFAULT 42,
  b text DEFAULT 'dflt', c int DEFAULT 7, g int GENERATED ALWAYS AS (coalesce(a, 0) * 2) STORED);
CREATE FUNCTION stmt285() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN RAISE NOTICE 'statement % %', TG_WHEN, TG_OP; RETURN NULL; END $$;
CREATE TRIGGER before285 BEFORE INSERT ON dst285 FOR EACH STATEMENT EXECUTE FUNCTION stmt285();
CREATE TRIGGER after285 AFTER INSERT ON dst285 FOR EACH STATEMENT EXECUTE FUNCTION stmt285();
CREATE RULE also285 AS ON INSERT TO src285 DO ALSO
  INSERT INTO dst285 (id, a, b, c, g) VALUES (DEFAULT, new.a, DEFAULT, 1, DEFAULT),
    (DEFAULT, new.a * 10, new.b, DEFAULT, DEFAULT), (DEFAULT, DEFAULT, 'x', 2, DEFAULT);
INSERT INTO src285 VALUES (1, 'one'), (2, 'two');
SELECT * FROM dst285 ORDER BY id;
CREATE TABLE inst285 (a int, b text);
CREATE RULE inst285 AS ON INSERT TO inst285 DO INSTEAD
  INSERT INTO dst285 (a, b) VALUES (new.a, DEFAULT), (new.a + 100, new.b) RETURNING dst285.a, dst285.b;
INSERT INTO inst285 VALUES (5, 'five'), (6, 'six') RETURNING *;
CREATE TABLE all285 (a int);
CREATE RULE all285 AS ON INSERT TO all285 DO INSTEAD
  INSERT INTO dst285 (a, b) VALUES (DEFAULT, DEFAULT), (DEFAULT, DEFAULT) RETURNING a;
INSERT INTO all285 VALUES (1), (2) RETURNING *;
CREATE RULE dv285 AS ON INSERT TO all285 WHERE new.a > 10 DO INSTEAD INSERT INTO dst285 DEFAULT VALUES;
INSERT INTO all285 VALUES (11), (12);
INSERT INTO all285 VALUES (11) RETURNING *;
SELECT * FROM dst285 ORDER BY id;
-- RETURNING lists are checked against the rule relation's row.
CREATE TABLE s285 (a int, b varchar(5), c numeric(6,2));
CREATE TABLE d285 (a int, b varchar(5), c numeric(6,2), e text);
CREATE RULE few285 AS ON INSERT TO s285 DO INSTEAD INSERT INTO d285 VALUES (new.a, new.b, new.c) RETURNING a, b;
CREATE RULE type285 AS ON INSERT TO s285 DO INSTEAD INSERT INTO d285 VALUES (new.a, new.b, new.c) RETURNING a, e, c;
CREATE RULE size285 AS ON INSERT TO s285 DO INSTEAD INSERT INTO d285 VALUES (new.a, new.b, new.c) RETURNING a, b::varchar(3), c;
CREATE RULE many285 AS ON UPDATE TO s285 DO INSTEAD UPDATE d285 SET a = new.a WHERE d285.a = old.a RETURNING d285.a, old.a, old.b, old.c;
CREATE RULE two285 AS ON INSERT TO s285 DO INSTEAD (INSERT INTO d285 VALUES (new.a) RETURNING a, b, c; INSERT INTO d285 VALUES (1) RETURNING a, b, c);
CREATE RULE cond285 AS ON INSERT TO s285 WHERE new.a > 0 DO INSTEAD INSERT INTO d285 VALUES (new.a) RETURNING a, b, c;
CREATE RULE also_ret285 AS ON INSERT TO s285 DO ALSO INSERT INTO d285 VALUES (new.a) RETURNING a, b, c;
CREATE RULE r1_285 AS ON INSERT TO s285 DO INSTEAD INSERT INTO d285 VALUES (new.a, new.b, new.c) RETURNING a, b, c;
CREATE RULE r2_285 AS ON INSERT TO s285 DO INSTEAD INSERT INTO d285 VALUES (new.a + 1, new.b, new.c) RETURNING a, b, c;
INSERT INTO s285 VALUES (1, 'x', 1.5);
INSERT INTO s285 VALUES (1, 'x', 1.5) RETURNING *;
DROP RULE r1_285 ON s285;
DROP RULE r2_285 ON s285;
CREATE RULE q285 AS ON INSERT TO s285 WHERE new.a > 5 DO INSTEAD INSERT INTO d285 VALUES (new.a);
INSERT INTO s285 VALUES (1) RETURNING *;
CREATE RULE n285 AS ON DELETE TO s285 DO INSTEAD NOTHING;
DELETE FROM s285 RETURNING *;
SELECT * FROM d285 ORDER BY a;
-- An INSTEAD OF trigger's view takes view-column defaults for columns the
-- INSERT leaves out or writes as DEFAULT, also from a rule's VALUES action.
CREATE VIEW v285 AS SELECT 1 AS x, 'v'::text AS y;
CREATE TABLE vlog285 (x int, y text);
CREATE FUNCTION v285() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN INSERT INTO vlog285 VALUES (NEW.x, NEW.y); RETURN NEW; END $$;
CREATE TRIGGER v285 INSTEAD OF INSERT ON v285 FOR EACH ROW EXECUTE FUNCTION v285();
ALTER VIEW v285 ALTER COLUMN y SET DEFAULT 'vdef';
INSERT INTO v285 VALUES (DEFAULT, DEFAULT), (5, 'five');
INSERT INTO v285 (x) VALUES (6);
INSERT INTO v285 (x) SELECT 7;
CREATE TABLE vsrc285 (a int);
CREATE RULE vsrc285 AS ON INSERT TO vsrc285 DO ALSO INSERT INTO v285 VALUES (new.a, DEFAULT), (new.a + 1, 'z');
INSERT INTO vsrc285 VALUES (10);
SELECT * FROM vlog285;
CREATE TABLE w285t (a int);
CREATE VIEW w285 AS SELECT a, a + 1 AS b FROM w285t;
ALTER VIEW w285 ALTER COLUMN b SET DEFAULT 5;
ALTER VIEW w285 ALTER COLUMN b SET DEFAULT 'x';
